import { z } from "zod";

export const planningModeSchema = z.enum(["single", "daily", "weekly"]);
export const visitSchema = z.object({
  accountName: z.string().trim().min(1).max(120),
  accountType: z.string().trim().min(1).max(80),
  contactName: z.string().trim().max(120).optional(),
  contactNames: z.array(z.string().trim().min(1).max(120)).max(25).optional(),
  contactTitle: z.string().trim().min(1).max(100),
  diseaseFocus: z.string().trim().min(1).max(120),
  visitObjective: z.string().trim().min(1).max(500),
  scheduledAt: z.string().datetime().optional(),
  durationMinutes: z.number().int().min(5).max(480).optional(),
  timezone: z.string().trim().min(1).max(80).optional(),
  location: z.string().trim().max(500).optional(),
  remindersMinutes: z.array(z.number().int().min(0).max(40_320)).max(5).optional(),
  notes: z.string().trim().max(2_000).optional(),
}).strict();
export const inputSchema = z.object({
  planningMode: planningModeSchema.default("single"),
  accountName: z.string().trim().max(120).optional(),
  contactNames: z.array(z.string().trim().min(1).max(120)).max(25).optional(),
  accountType: z.string().trim().max(80).optional(),
  contactTitle: z.string().trim().max(100).optional(),
  diseaseFocus: z.string().trim().max(120).optional(),
  visitObjective: z.string().trim().max(500).optional(),
  scheduledAt: z.string().datetime().optional(),
  durationMinutes: z.number().int().min(5).max(480).optional(),
  timezone: z.string().trim().min(1).max(80).optional(),
  location: z.string().trim().max(500).optional(),
  remindersMinutes: z.array(z.number().int().min(0).max(40_320)).max(5).optional(),
  accountContext: z.string().trim().max(20_000).optional(),
  planningPeriod: z.string().trim().max(120).optional(),
  visits: z.array(visitSchema).max(25).optional(),
}).strict().superRefine((value, context) => {
  if (value.planningMode === "single") {
    for (const key of ["accountType", "contactTitle", "diseaseFocus", "visitObjective"] as const) {
      if (!value[key]) context.addIssue({ code: "custom", path: [key], message: `${key} is required for a single plan` });
    }
  } else if (!value.visits?.length) context.addIssue({ code: "custom", path: ["visits"], message: "At least one visit is required" });
});
export const objectionSchema = z.object({ objection: z.string().min(1), tellMeMoreProbes: z.array(z.string().min(1)).min(1).max(4), feel: z.string().min(1), felt: z.string().min(1), found: z.string().min(1) }).strict();
export const visitPlanSchema = z.object({ accountName: z.string().min(1), refinedObjective: z.string().min(1), discoveryQuestions: z.array(z.string().min(1)).min(2).max(8), likelyObjections: z.array(objectionSchema).max(5), nextStepPlan: z.string().min(1), preparationChecklist: z.array(z.string().min(1)).max(8), qualityScore: z.number().min(0).max(100) }).strict();
export const outputSchema = z.object({ refinedObjective: z.string().min(1), discoveryQuestions: z.array(z.string().min(1)).min(2).max(8), likelyObjections: z.array(objectionSchema).max(5), nextStepPlan: z.string().min(1), preparationChecklist: z.array(z.string().min(1)).max(8), qualityScore: z.number().min(0).max(100), visitPlans: z.array(visitPlanSchema).max(25) }).strict();
export type ToolInput = z.infer<typeof inputSchema>;
export type ToolOutput = z.infer<typeof outputSchema>;
