import OpenAI from "openai";
import { zodTextFormat } from "openai/helpers/zod";
import { ZodError } from "zod";
import { outputSchema, type ToolInput, type ToolOutput } from "./schema.js";
import { SYSTEM_PROMPT, buildPrompt } from "./prompt.js";

export interface ProviderUsage { inputTokens: number; outputTokens: number; totalTokens: number; }
export interface ProviderResult { output: ToolOutput; responseId?: string; model: string; usage?: ProviderUsage; }
export interface ProviderOptions { requestId?: string; timeoutMs?: number; maxSchemaRetries?: number; maxOutputTokens?: number; safetyIdentifier?: string; }
export interface ToolProvider { generate(input: ToolInput, options?: ProviderOptions): Promise<ProviderResult>; }
export interface OpenAIProviderConfig { apiKey?: string; model?: string; timeoutMs?: number; reasoningEffort?: "none" | "minimal" | "low" | "medium" | "high"; client?: OpenAI; }
export class ProviderError extends Error { constructor(readonly code: string, readonly status: number, readonly retryable: boolean, message: string) { super(message); } }
class StructuredOutputError extends Error {}
const isRepairable = (error: unknown) => error instanceof StructuredOutputError || error instanceof ZodError || error instanceof SyntaxError;
function publicProviderError(error: unknown): ProviderError { const status = typeof error === "object" && error && "status" in error && typeof error.status === "number" ? error.status : 502; if (status === 401 || status === 403) return new ProviderError("PROVIDER_AUTH", 503, false, "AI service authentication failed"); if (status === 429) return new ProviderError("RATE_LIMITED", 429, true, "AI service is busy; try again shortly"); if (status === 408) return new ProviderError("TIMEOUT", 504, true, "AI request timed out"); return new ProviderError("PROVIDER_FAILED", 502, status >= 500, "AI service could not complete the request"); }

export class OpenAIResponsesProvider implements ToolProvider {
  private readonly client: OpenAI; private readonly model: string; private readonly timeoutMs: number; private readonly reasoningEffort: "minimal" | "low" | "medium" | "high";
  constructor(config: OpenAIProviderConfig = {}) { const apiKey = config.apiKey ?? process.env.OPENAI_API_KEY; if (!config.client && !apiKey) throw new ProviderError("PROVIDER_NOT_CONFIGURED", 503, false, "AI service is not configured"); this.client = config.client ?? new OpenAI({ apiKey, timeout: config.timeoutMs ?? 30_000 }); this.timeoutMs = config.timeoutMs ?? 30_000; this.model = config.model ?? process.env.OPENAI_MODEL ?? "gpt-5.6-sol"; this.reasoningEffort = config.reasoningEffort === "none" ? "minimal" : config.reasoningEffort ?? "low"; }
  async generate(input: ToolInput, options: ProviderOptions = {}): Promise<ProviderResult> { const retries = Math.max(0, Math.min(options.maxSchemaRetries ?? 1, 1)); let repair = ""; for (let attempt = 0; attempt <= retries; attempt += 1) { try { const response = await this.client.responses.parse({ model: this.model, store: false, reasoning: { effort: this.reasoningEffort }, max_output_tokens: options.maxOutputTokens ?? 4_000, safety_identifier: options.safetyIdentifier, input: [{ role: "system", content: SYSTEM_PROMPT }, { role: "user", content: buildPrompt(input) + repair }], text: { format: zodTextFormat(outputSchema, "pre_call_planner"), verbosity: "medium" } }, { timeout: options.timeoutMs ?? this.timeoutMs, headers: options.requestId ? { "X-Client-Request-Id": options.requestId } : undefined }); if (!response.output_parsed) throw new StructuredOutputError("No parsed structured output"); const usage = response.usage ? { inputTokens: response.usage.input_tokens, outputTokens: response.usage.output_tokens, totalTokens: response.usage.total_tokens } : undefined; return { output: outputSchema.parse(response.output_parsed), responseId: response.id, model: this.model, usage }; } catch (error) { if (attempt < retries && isRepairable(error)) { repair = "\n\nYour previous answer did not match the required schema. Return every required field with valid values."; continue; } if (isRepairable(error)) throw new ProviderError("INVALID_MODEL_OUTPUT", 502, true, "AI returned an invalid structured response"); throw publicProviderError(error); } } throw new ProviderError("PROVIDER_FAILED", 502, true, "AI service could not complete the request"); }
}
